import XCTest
@testable import ScionicMerkleTree

/// THE UNIFICATION TEST: Verifies that Swift leaf hashing produces IDENTICAL
/// CID hashes to the Go implementation.
///
/// If these tests pass, the entire CBOR → SHA256 → CID → base32lower pipeline
/// is byte-compatible with Go's fxamacker/cbor + go-cid + go-multihash.
///
/// Reference values generated by TestCrossCompatLeafHashes in the Go project.
final class CrossCompatLeafTests: XCTestCase {

    // MARK: - Test 1: Simple file leaf, no content, no additional data

    func testSimpleFileLeaf_HashMatchesGo() throws {
        let builder = DagLeafBuilder(name: "test.txt")
        builder.setType(.file)

        let leaf = try builder.buildLeaf(additionalData: nil)

        let expected = "bafireibuicwfb4ui2mth5zis4sgurvaoc4ksl2c74ezmjvuzqxdzkdeazq"
        XCTAssertEqual(leaf.hash, expected,
            "🔴 LEAF HASH MISMATCH! Swift CID does not match Go CID for simple file leaf.")
        XCTAssertEqual(leaf.type, .file)
        XCTAssertEqual(leaf.currentLinkCount, 0)
        XCTAssertNil(leaf.contentHash)

        // Verify the leaf can self-verify
        try leaf.verifyLeaf()
    }

    // MARK: - Test 2: File leaf with content

    func testFileLeafWithContent_HashMatchesGo() throws {
        let builder = DagLeafBuilder(name: "hello.txt")
        builder.setType(.file)
        builder.setData(Data("Hello, World!".utf8))

        let leaf = try builder.buildLeaf(additionalData: nil)

        let expected = "bafireiflmfq3vajjy5swuz2ayvewhgm2g3nurum6hrizwo4ypic33ke3yu"
        XCTAssertEqual(leaf.hash, expected,
            "🔴 LEAF HASH MISMATCH! Swift CID does not match Go CID for file leaf with content.")
        XCTAssertNotNil(leaf.contentHash)

        try leaf.verifyLeaf()
    }

    // MARK: - Test 3: Chunk leaf

    func testChunkLeaf_HashMatchesGo() throws {
        let builder = DagLeafBuilder(name: "0")
        builder.setType(.chunk)
        builder.setData(Data("chunk data here".utf8))

        let leaf = try builder.buildLeaf(additionalData: nil)

        let expected = "bafireiankzjounqke5zgzgybia53orcs4xudtpg7ab7cgcobgbvemovv5m"
        XCTAssertEqual(leaf.hash, expected,
            "🔴 LEAF HASH MISMATCH! Swift CID does not match Go CID for chunk leaf.")

        try leaf.verifyLeaf()
    }

    // MARK: - Test 4: File leaf with additional data

    func testFileLeafWithAdditionalData_HashMatchesGo() throws {
        let builder = DagLeafBuilder(name: "meta.txt")
        builder.setType(.file)
        builder.setData(Data("content".utf8))

        let additionalData = [
            "author": "test",
            "version": "1.0",
        ]

        let leaf = try builder.buildLeaf(additionalData: additionalData)

        let expected = "bafireic7msahojyf4q3xpjtrnrveqkvy7w4y24gx66m7h5xjqgmekapmsy"
        XCTAssertEqual(leaf.hash, expected,
            "🔴 LEAF HASH MISMATCH! Swift CID does not match Go CID for leaf with additional data.")

        try leaf.verifyLeaf()
    }

    // MARK: - Test 5: Full DAG (root with 2 children) — the ultimate test

    func testFullDag_RootHashMatchesGo() throws {
        let dagBuilder = DagBuilder()

        // Child 1
        let child1Builder = DagLeafBuilder(name: "file1.txt")
        child1Builder.setType(.file)
        child1Builder.setData(Data("file one content".utf8))
        let child1 = try child1Builder.buildLeaf(additionalData: nil)
        dagBuilder.addLeaf(child1, parent: nil)

        // Child 2
        let child2Builder = DagLeafBuilder(name: "file2.txt")
        child2Builder.setType(.file)
        child2Builder.setData(Data("file two content".utf8))
        let child2 = try child2Builder.buildLeaf(additionalData: nil)
        dagBuilder.addLeaf(child2, parent: nil)

        // Verify children match Go
        XCTAssertEqual(child1.hash, "bafireiglie6hokrajhseihtblq24ckpxverf6owidzeey63oqadljd2xfy",
            "🔴 Child 1 hash mismatch!")
        XCTAssertEqual(child2.hash, "bafireiahteebcm75zwg7pzo2pvtjejrepxhtogx6p32yr35me3wnieqdra",
            "🔴 Child 2 hash mismatch!")

        // Root (directory with 2 children)
        let rootBuilder = DagLeafBuilder(name: "mydir")
        rootBuilder.setType(.directory)
        rootBuilder.addLink(child1.hash)
        rootBuilder.addLink(child2.hash)

        let rootLeaf = try rootBuilder.buildRootLeaf(dag: dagBuilder, additionalData: nil)

        // THE MOMENT OF TRUTH
        let expectedRoot = "bafireiglw5me5qi2vhuvkc3f6tygpqvcjvsgmj6zgppdrz7hwvxbopq2iy"
        XCTAssertEqual(rootLeaf.hash, expectedRoot,
            "🔴🔴🔴 ROOT HASH MISMATCH! The full DAG root CID does not match Go! 🔴🔴🔴")

        // Verify metadata matches Go
        XCTAssertEqual(rootLeaf.leafCount, 3, "LeafCount mismatch")
        XCTAssertEqual(rootLeaf.contentSize, 32, "ContentSize mismatch")
        XCTAssertEqual(rootLeaf.dagSize, 677, "DagSize mismatch")

        // Verify children can self-verify
        try child1.verifyLeaf()
        try child2.verifyLeaf()
    }
}